import abc
import asyncio
import getpass
import logging
import os
import platform
import sqlite3

from pathlib import Path

import aiosqlite

GET_ALL_TABLES_SQL = "SELECT name FROM sqlite_master WHERE type='table';"


class SharedProxyDb(metaclass=abc.ABCMeta):
    """Class to manage the UE proxies database."""

    PROXIES_DB_DIR = Path(os.path.expanduser("~")) / ".taf/ue"
    lock = asyncio.Lock()  # Class-level lock for thread safety

    def __init__(self):
        """Initialize the ProxyDatabaseManager class."""
        self.db_path = self.PROXIES_DB_DIR / "ueproxies.db"
        self.logger = logging.getLogger(__name__)
        self._is_user_an_admin = None
        self.__setup_database()

    @abc.abstractproperty
    def TABLE_NAME(self) -> str:
        """Return the name of the table managed by this class."""
        ...

    @abc.abstractmethod
    async def optional_create_table(self) -> bool:
        """
        Create actual table if it doesn't exist.
        Note: It is prohibited to use `commit_sql` inside this method (use 'commit_sql_and_raise_on_failure' instead)!

        :returns: True if successful, False otherwise.
        """
        ...

    async def execute_sql(self, *args, **kwargs) -> list:
        """
        Execution a raw SQL command and return the results.
        Note: SQL execution does not require table present, because it returns fetched data only!

        :param args: SQL command and parameters.
        :param kwargs: Additional keyword arguments for cursor.execute.
        :returns: The results of the SQL command. In case of error, an empty list is returned.
        """
        if not await self.__acquire_with_timeout():
            self.logger.warning(f"Shared DB ('{self.TABLE_NAME}'): Timeout acquiring database lock in `execute_sql`.")
            return []
        try:
            async with aiosqlite.connect(self.db_path) as conn:
                async with conn.execute(*args, **kwargs) as cursor:
                    return await cursor.fetchall()
        except sqlite3.Error:
            return []
        finally:
            self.lock.release()

    async def commit_sql_and_raise_on_failure(self, *args, **kwargs) -> None:
        """
        Commit a raw SQL command to add, remove or update table contents.
        Note: This method can raise exceptions on failure.
        Note: To use this method safely (DB with table write access), please use `commit_sql_safe` instead.

        :param args: SQL command and parameters.
        :param kwargs: Additional keyword arguments for cursor.execute.
        :returns: None
        :raises: TimeoutError if lock acquisition times out, sqlite3.Error on SQL execution errors.
        :raises: Indirect sqlite3.Error on SQL execution errors.
        """
        if not await self.__acquire_with_timeout():
            raise TimeoutError("Timeout acquiring database lock in 'commit_sql_and_raise_on_failure'.")
        try:
            async with aiosqlite.connect(self.db_path) as conn:
                await conn.execute(*args, **kwargs)
                await conn.commit()
        finally:
            self.lock.release()

    async def commit_sql(self, *args, **kwargs) -> None:
        """
        Safe commit a raw SQL command to add, remove or update table contents.

        :param args: SQL command and parameters.
        :param kwargs: Additional keyword arguments for cursor.execute.
        """
        # Check for admin privileges and abort if detected
        if self.__is_user_an_admin():
            self.logger.warning(f"Shared DB ('{self.TABLE_NAME}'): Cannot modify database as admin/root user")
            return

        # Check if table exists otherwise create it. When failed abort with an exception.
        if not await self.optional_create_table():
            msg_error = f"Shared DB ('{self.TABLE_NAME}'): Failed to create or access the required table."
            self.logger.warning(msg_error)
            return

        try:
            await self.commit_sql_and_raise_on_failure(*args, **kwargs)
        except (TimeoutError, sqlite3.Error) as e:
            self.logger.warning(f"Shared DB ('{self.TABLE_NAME}'): Failed to commit SQL command: {e}")

    async def get_all_tables(self) -> list:
        """
        Retrieve all table names from the database file.

        :returns: List of table names.
        """
        return [row[0] for row in await self.execute_sql(GET_ALL_TABLES_SQL)]

    def __is_user_an_admin(self) -> bool:
        """Check if the current user has admin/root privileges (True if user has admin privileges)."""
        if self._is_user_an_admin is not None:
            return self._is_user_an_admin
        try:
            if platform.system().lower() == "windows":
                # import here to avoid issues on non-Windows systems with unstable ctypes import
                import ctypes  # noqa: E402
                self._is_user_an_admin = ctypes.windll.shell32.IsUserAnAdmin() != 0
            else:
                # For Unix-like systems, check which (root)
                self._is_user_an_admin = getpass.getuser().lower() == "root"
        except Exception as e:
            self.logger.debug(f"Shared DB ('{self.TABLE_NAME}'): Failed to check admin status: {e}")
            self._is_user_an_admin = False
        return self._is_user_an_admin

    def __setup_database(self) -> None:
        """Set up the database directory and file if they don't exist."""
        # Check for admin privileges and abort if detected
        if self.__is_user_an_admin():
            self.logger.debug(f"Shared DB ('{self.TABLE_NAME}'): Running as admin/root! Files may not be created or "
                              "modified.")
            return

        # Create directory if it doesn't exist
        if not self.PROXIES_DB_DIR.exists():
            try:
                self.PROXIES_DB_DIR.mkdir(parents=True, exist_ok=True)
                self.logger.debug(f"Shared DB ('{self.TABLE_NAME}'): Created directory: {self.PROXIES_DB_DIR}")
            except Exception as e:
                self.logger.debug(f"Shared DB ('{self.TABLE_NAME}'): Failed to create directory {self.PROXIES_DB_DIR}: "
                                  f"{e}")
                return

    async def __acquire_with_timeout(self, timeout=1):
        try:
            await asyncio.wait_for(self.lock.acquire(), timeout)
            return True
        except TimeoutError:
            return False
